import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import type { FilterDataStructure, FilterForm } from 'models/Filters';

import type { CommercialResultsSubFilters } from './getCommercialResultsSubFilters';

const ALL = 'All';

const COMMERCIAL_RESULTS_FILTER_HIERARCHY: Array<
  keyof CommercialResultsSubFilters
> = ['country', 'region', 'channel', 'brand', 'sub_brand', 'pack_type', 'sku'];

const getActiveFilterKey = (
  subFilters: CommercialResultsSubFilters,
): keyof CommercialResultsSubFilters | undefined => {
  for (
    let index = COMMERCIAL_RESULTS_FILTER_HIERARCHY.length - 1;
    index >= 0;
    index -= 1
  ) {
    const filterKey = COMMERCIAL_RESULTS_FILTER_HIERARCHY[index];

    if (subFilters[filterKey] !== ALL) {
      return filterKey;
    }
  }

  return undefined;
};

const getCountryDisplayLabel = (
  dataFilters: FilterDataStructure | undefined,
  countryCode: string,
  applied: FilterForm,
): string => {
  if (!countryCode || countryCode === ALL) {
    return ALL;
  }

  if (countryCode === 'ABI') {
    if (applied.zone === 'EUR') {
      return 'Europe';
    }

    return 'Global';
  }

  if (dataFilters && applied.country === countryCode) {
    const country = FilterDataAccessor.getInstance().getCountry(
      dataFilters,
      applied,
    );

    if (country?.label) {
      return String(country.label);
    }
  }

  if (dataFilters) {
    const countryOption = FilterDataAccessor.getInstance()
      .getCountryOptions(dataFilters)
      .find((option) => option.value === countryCode);

    if (countryOption?.label) {
      return String(countryOption.label);
    }
  }

  return countryCode;
};

export function getCommercialResultsLineBarChartFilteredBy(
  subFilters: CommercialResultsSubFilters,
): string {
  const filterKey = getActiveFilterKey(subFilters);

  if (!filterKey) {
    return ALL;
  }

  return subFilters[filterKey];
}

export function getCommercialResultsLineBarChartFilteredByDisplayValue(
  subFilters: CommercialResultsSubFilters,
  dataFilters: FilterDataStructure | undefined,
  applied: FilterForm,
): string {
  const filterKey = getActiveFilterKey(subFilters);

  if (!filterKey) {
    return ALL;
  }

  const rawValue = subFilters[filterKey];

  if (filterKey === 'country') {
    return getCountryDisplayLabel(dataFilters, rawValue, applied);
  }

  return rawValue;
}
